import { beforeAll, describe, expect, it } from "vitest";
import initMathlexWasm from "./wasm/jabr_mathlex";
import {
  latexExpressionToLatex,
  mathExpressionToLatex,
  parseLatexExpression,
  parseMathExpression,
} from "./mathlex";

// The WASM package is generated by scripts/build-wasm.mjs before this suite runs.
// Supplying the bytes avoids relying on browser fetch() or a relative URL in Node.
beforeAll(async () => {
  const bun = (globalThis as typeof globalThis & {
    Bun: { file(path: URL): { arrayBuffer(): Promise<ArrayBuffer> } };
  }).Bun;
  const wasmBytes = await bun.file(new URL("./wasm/jabr_mathlex_bg.wasm", import.meta.url)).arrayBuffer();
  await initMathlexWasm(wasmBytes);
});

describe("Mathlex real WebAssembly integration", () => {
  it("parses a plain expression into the expected AST", async () => {
    const ast = await parseMathExpression("2*x + sin(y)^2");
    expect(ast.kind).toBe("Binary");
    expect((ast.value as { op: { kind: string } }).op.kind).toBe("Add");
  });

  it("parses LaTeX with literal backslashes", async () => {
    const ast = await parseLatexExpression("\\frac{1}{2}");
    expect(typeof ast.kind).toBe("string");
    expect(ast.kind.length).toBeGreaterThan(0);
    await expect(latexExpressionToLatex("\\frac{1}{2}")).resolves.toBe("\\frac{1}{2}");
  });

  it("parses apostrophe derivative and transpose notation", async () => {
    await expect(parseMathExpression("x' + y''")).resolves.toMatchObject({ kind: "Binary" });
  });

  it("serializes a plain expression to LaTeX through the real WASM module", async () => {
    await expect(mathExpressionToLatex("2*x + 3")).resolves.toBe("2 \\cdot x + 3");
  });

  it("returns parser errors from the real WASM module", async () => {
    await expect(parseLatexExpression("\\frac{1}{")).rejects.toBeTruthy();
  });
});
